// VU1 microcode runtime for Road Trip (stage A of docs/graphics-plan.md).
//
// The game's single VU1 microcode image is translated ahead of time into C++ (vu1_microcode.gen.cpp,
// generated by scripts/vu/vu2cpp.py). It runs against this state exactly as the hardware program runs
// against VU1 registers and data memory, and hands every XGKICK'd GIF packet to a GifSink.
//
// Arithmetic mirrors the reference interpreter scripts/vu/vusim.py bit for bit (validated against
// PCSX2): float32 operations rounded toward zero (Run() sets the SSE rounding mode for its duration), no
// Inf/NaN (overflow saturates to +-FLT_MAX), denormals read as zero, and FMAND seeing the MAC flags from
// 4 instruction pairs earlier. Requires SSE2 float math (the v141 x86 default).
#pragma once

#include <stdint.h>

namespace vu1 {

struct State {
    uint32_t mem[1024][4];   // 16 KB data memory, qword-addressed
    uint32_t vf[32][4];      // raw bit patterns; vf00 is (0,0,0,1)
    uint16_t vi[16];
    uint32_t acc[4];
    uint32_t q, i;
    uint32_t clip;           // 24-bit clip flag history
    uint32_t mac;            // MAC flags: S in bits 7..4 (x..w), Z in bits 3..0
    uint32_t macRing[4];     // MAC after each of the last 4 pairs; [0] is what FMAND reads
    uint16_t top;            // XTOP value for the current call
};

// Receives each GIF packet kicked by the microcode (copied out of data memory, tags included).
class GifSink {
public:
    virtual ~GifSink() {}
    virtual void Kick(uint16_t vuAddr, const uint32_t (*qwords)[4], int count) = 0;
};

void Reset(State& s);   // zero everything, set vf00 = (0,0,0,1)

// Run the microprogram at byte address `entry` (an MSCAL target: 0x00, 0x10 ... 0x70) with XTOP = top.
// Returns false if the program didn't end within a sane number of steps.
bool Run(State& s, uint32_t entry, uint16_t top, GifSink& sink);

}  // namespace vu1
